import logging
from six.moves.urllib.parse import urljoin

from scrapy.http import HtmlResponse
from scrapy.utils.response import get_meta_refresh
from scrapy.utils.python import to_native_str
from scrapy.exceptions import IgnoreRequest, NotConfigured

logger = logging.getLogger(__name__)


class BaseRedirectMiddleware(object):

    enabled_setting = 'REDIRECT_ENABLED'

    def __init__(self, settings):
        if not settings.getbool(self.enabled_setting):
            raise NotConfigured

        self.max_redirect_times = settings.getint('REDIRECT_MAX_TIMES')
        self.priority_adjust = settings.getint('REDIRECT_PRIORITY_ADJUST')

    @classmethod
    def from_crawler(cls, crawler):
        return cls(crawler.settings)

    def _redirect(self, redirected, request, spider, reason):
        remaining_ttl = request.meta.setdefault('redirect_ttl', self.max_redirect_times)
        count = 1 + request.meta.get('redirect_times', 0)

        if remaining_ttl and count <= self.max_redirect_times:
            redirected.meta['redirect_times'] = count
            redirected.meta['redirect_ttl'] = remaining_ttl - 1
            previous_urls = request.meta.get('redirect_urls', [])
            redirected.meta['redirect_urls'] = previous_urls + [request.url]
            redirected.dont_filter = request.dont_filter
            redirected.priority = self.priority_adjust + request.priority
            logger.debug("Redirecting (%(reason)s) to %(redirected)s from %(request)s",
                         {'reason': reason, 'redirected': redirected, 'request': request},
                         extra={'spider': spider})
            return redirected
        logger.debug("Discarding %(request)s: max redirections reached",
                     {'request': request}, extra={'spider': spider})
        raise IgnoreRequest("max redirections reached")

    def _redirect_request_using_get(self, request, redirect_url):
        new_request = request.replace(url=redirect_url, method='GET', body='')
        for header_name in ('Content-Type', 'Content-Length'):
            new_request.headers.pop(header_name, None)
        return new_request


class RedirectMiddleware(BaseRedirectMiddleware):
    """Handle redirection of requests based on response status and meta-refresh html tag"""

    def process_response(self, request, response, spider):
        status = response.status
        skip = (request.meta.get('dont_redirect', False) or
                status in getattr(spider, 'handle_httpstatus_list', []) or
                status in request.meta.get('handle_httpstatus_list', []) or
                request.meta.get('handle_httpstatus_all', False))
        if skip:
            return response

        allowed_codes = (301, 302, 303, 307)
        if 'Location' not in response.headers or status not in allowed_codes:
            return response

        # HTTP header is ascii or latin1, redirected url will be percent-encoded utf-8
        loc = to_native_str(response.headers['location'].decode('latin1'))

        target_url = urljoin(request.url, loc)

        if status in (301, 307) or request.method == 'HEAD':
            new_req = request.replace(url=target_url)
            return self._redirect(new_req, request, spider, status)

        new_req = self._redirect_request_using_get(request, target_url)
        return self._redirect(new_req, request, spider, status)


class MetaRefreshMiddleware(BaseRedirectMiddleware):

    enabled_setting = 'METAREFRESH_ENABLED'

    def __init__(self, settings):
        super(MetaRefreshMiddleware, self).__init__(settings)
        self._maxdelay = settings.getint('REDIRECT_MAX_METAREFRESH_DELAY',
                                         settings.getint('METAREFRESH_MAXDELAY'))

    def process_response(self, request, response, spider):
        if request.meta.get('dont_redirect', False) or request.method == 'HEAD' or \
                not isinstance(response, HtmlResponse):
            return response

        if isinstance(response, HtmlResponse):
            delay, target = get_meta_refresh(response)
            if target and delay < self._maxdelay:
                new_req = self._redirect_request_using_get(request, target)
                return self._redirect(new_req, request, spider, 'meta refresh')

        return response

